#!/usr/bin/env bun

/**
 * Generate API reference from @rnforge/react-native-in-app-updates
 *
 * This script:
 * 1. Runs TypeDoc to generate markdown in a temp directory
 * 2. Concatenates all generated files into a single reference.mdx
 * 3. Adds a header explaining the file is auto-generated
 * 4. Cleans up the temp directory
 */

import { spawnSync } from "child_process";
import { readFileSync, writeFileSync, mkdirSync, rmSync, readdirSync, statSync, existsSync } from "fs";
import { join } from "path";

const PACKAGE_NAME = "@rnforge/react-native-in-app-updates";
const PACKAGE_REPO = "../react-native-in-app-updates";
const TEMP_DIR = ".typedoc-temp";
const OUTPUT_FILE = "content/docs/packages/react-native-in-app-updates/reference.mdx";

function runTypedoc() {
  console.log("Running TypeDoc...");

  // Clean temp directory
  if (existsSync(TEMP_DIR)) {
    rmSync(TEMP_DIR, { recursive: true });
  }
  mkdirSync(TEMP_DIR, { recursive: true });

  // Run TypeDoc
  const result = spawnSync("bunx", ["typedoc", "--options", "typedoc.json", "--out", TEMP_DIR], {
    stdio: "inherit",
    cwd: process.cwd(),
  });

  if (result.status !== 0) {
    console.error("TypeDoc failed");
    process.exit(1);
  }
}

function readAllMarkdown(dir, files = []) {
  const entries = readdirSync(dir);

  for (const entry of entries) {
    const fullPath = join(dir, entry);
    const stat = statSync(fullPath);

    if (stat.isDirectory()) {
      readAllMarkdown(fullPath, files);
    } else if (entry.endsWith(".mdx") || entry.endsWith(".md")) {
      files.push({
        path: fullPath,
        content: readFileSync(fullPath, "utf-8"),
      });
    }
  }

  return files;
}

function concatenateFiles(files) {
  // Separate index from other files
  const indexFile = files.find((f) => f.path.endsWith("index.mdx") || f.path.endsWith("index.md"));
  const otherFiles = files.filter((f) => f !== indexFile);

  // Sort other files by type (classes, functions, type-aliases)
  const sorted = otherFiles.sort((a, b) => {
    const aPath = a.path;
    const bPath = b.path;

    // Classes first, then functions, then type-aliases
    if (aPath.includes("classes") && !bPath.includes("classes")) return -1;
    if (!aPath.includes("classes") && bPath.includes("classes")) return 1;
    if (aPath.includes("functions") && !bPath.includes("functions")) return -1;
    if (!aPath.includes("functions") && bPath.includes("functions")) return 1;

    // Within same category, sort alphabetically
    return aPath.localeCompare(bPath);
  });

  let output = "";

  // Add index content (without the title since we'll add our own)
  if (indexFile) {
    const lines = indexFile.content.split("\n");
    // Skip the first line if it's a title
    const startIndex = lines[0].startsWith("#") ? 1 : 0;
    output += lines.slice(startIndex).join("\n") + "\n\n";
  }

  // Add all other files
  for (const file of sorted) {
    output += file.content + "\n\n";
  }

  return output;
}

function stripTypeDocLinks(content) {
  // Strip TypeDoc cross-links to plain inline code
  // Pattern 1: [Name](relative/path.mdx) -> Name
  // Pattern 2: [`Name`](relative/path.mdx) -> `Name`
  // Pattern 3: [Name](Name.mdx) -> Name (same-directory links)
  
  let result = content;
  
  // Handle links with backticks inside: [`Name`](path) -> `Name`
  result = result.replace(/\[`([^`]+)`\]\([^)]+\)/g, '`$1`');
  
  // Handle links with directory prefixes: [Name](classes/...), [Name](type-aliases/...), etc.
  result = result.replace(/\[([^\]]+)\]\((?:classes|type-aliases|functions|\.\.\/)[^)]+\)/g, '$1');
  
  // Handle same-directory links: [Name](Name.mdx) -> Name
  result = result.replace(/\[([^\]]+)\]\([^)]+\.mdx\)/g, '$1');
  
  return result;
}

function addHeader(content) {
  const header = `---
title: API Reference
description: Auto-generated API reference for ${PACKAGE_NAME}
---

{/*
  AUTO-GENERATED FILE - DO NOT EDIT MANUALLY

  Package: ${PACKAGE_NAME}
  Source: ${PACKAGE_NAME}/src
  Source repository: https://github.com/rnforge/react-native-in-app-updates

  This file was generated by TypeDoc from the package's TypeScript definitions.
  To regenerate, run: bun run gen:api-reference
*/}

# API Reference

This is the auto-generated API reference for \`${PACKAGE_NAME}\`.

For a human-readable guide with examples, see the [API Guide](./api).

`;

  return header + content;
}

function main() {
  try {
    runTypedoc();

    console.log("Reading generated files...");
    const files = readAllMarkdown(TEMP_DIR);

    console.log(`Found ${files.length} files`);

    console.log("Concatenating...");
    const concatenated = concatenateFiles(files);

    console.log("Stripping TypeDoc cross-links...");
    const cleaned = stripTypeDocLinks(concatenated);

    console.log("Adding header...");
    const withHeader = addHeader(cleaned);

    console.log(`Writing to ${OUTPUT_FILE}...`);
    writeFileSync(OUTPUT_FILE, withHeader);

    console.log("Cleaning up...");
    rmSync(TEMP_DIR, { recursive: true });

    console.log("✓ API reference generated successfully");
  } catch (error) {
    console.error("Error:", error);
    // Clean up on error
    if (existsSync(TEMP_DIR)) {
      rmSync(TEMP_DIR, { recursive: true });
    }
    process.exit(1);
  }
}

main();
